def choose_move(observation):
    agent_pos = observation.get('agent_position', (0, 0))
    resources = observation.get('resources', [])
    enemies = observation.get('enemies', [])
    territory = observation.get('territory', {})

    x, y = agent_pos

    def move_towards(target_x, target_y):
        dx = target_x - x
        dy = target_y - y
        if dx != 0:
            dx = int(dx / abs(dx))
        else:
            dx = 0
        if dy != 0:
            dy = int(dy / abs(dy))
        else:
            dy = 0
        return [dx, dy]

    # Priority 1: Move towards nearest resource
    if resources:
        closest_resource = min(resources, key=lambda r: abs(r[0] - x) + abs(r[1] - y))
        rx, ry = closest_resource
        return move_towards(rx, ry)

    # Priority 2: Move towards nearest enemy
    if enemies:
        closest_enemy = min(enemies, key=lambda e: abs(e[0] - x) + abs(e[1] - y))
        ex, ey = closest_enemy
        return move_towards(ex, ey)

    # Priority 3: Move towards owned territory positions
    my_owner = territory.get('owner', None)
    if my_owner is not None:
        owned_positions = [pos for pos, owner in territory.items() if owner == my_owner]
        if owned_positions:
            closest_pos = min(owned_positions, key=lambda p: abs(p[0] - x) + abs(p[1] - y))
            px, py = closest_pos
            return move_towards(px, py)

    # Default: do not move
    return [0, 0]

